From 7525cb7528911d127f39defbbc32659c612da177 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 03:49:08 +0100
Subject: [PATCH] daemon: keep low battery notifications for peripherals until
 recharged

Notifications about a low mouse, keyboard or headset battery closed by
themselves after a few seconds and were easy to miss. Show them as critical
persistent notifications instead, and close them once the device recharges.

BUG: 447644
---
 daemon/powerdevilcore.cpp | 31 +++++++++++++++++++++----------
 daemon/powerdevilcore.h   |  3 +--
 2 files changed, 22 insertions(+), 12 deletions(-)

diff --git a/daemon/powerdevilcore.cpp b/daemon/powerdevilcore.cpp
index 33badced8..d10af663f 100644
--- a/daemon/powerdevilcore.cpp
+++ b/daemon/powerdevilcore.cpp
@@ -497,11 +497,6 @@ void Core::onDeviceRemoved(const QString &udi)
     m_batteriesCharged.remove(udi);
 }

-void Core::emitNotification(const QString &eventId, const QString &title, const QString &message, const QString &iconName)
-{
-    KNotification::event(eventId, title, message, iconName, KNotification::CloseOnTimeout, QStringLiteral("powerdevil"));
-}
-
 void Core::emitRichNotification(const QString &evid, const QString &title, const QString &message)
 {
     KNotification::event(evid, title, message, QPixmap(), KNotification::CloseOnTimeout, QStringLiteral("powerdevil"));
@@ -510,8 +505,15 @@ void Core::emitRichNotification(const QString &evid, const QString &title, const
 bool Core::emitBatteryChargePercentNotification(int currentPercent, int previousPercent, const QString &udi, Core::ChargeNotificationFlags flags)
 {
     if (m_peripheralBatteriesPercent.contains(udi)) {
+        if (currentPercent > m_globalSettings->peripheralBatteryLowLevel()) {
+            if (auto notification = m_peripheralBatteryNotifications.take(udi)) {
+                notification->close();
+            }
+            return false;
+        }
+
         // Show the notification just once on each normal->low transition
-        if (currentPercent > m_globalSettings->peripheralBatteryLowLevel() || previousPercent <= m_globalSettings->peripheralBatteryLowLevel()) {
+        if (previousPercent <= m_globalSettings->peripheralBatteryLowLevel()) {
             return false;
         }

@@ -575,7 +577,18 @@ bool Core::emitBatteryChargePercentNotification(int currentPercent, int previous
                 break;
             }

-            emitNotification(QStringLiteral("lowperipheralbattery"), title, msg, icon);
+            if (auto notification = m_peripheralBatteryNotifications.take(udi)) {
+                notification->close();
+            }
+
+            auto notification = new KNotification(QStringLiteral("lowperipheralbattery"), KNotification::Persistent, nullptr);
+            notification->setComponentName(QStringLiteral("powerdevil"));
+            notification->setTitle(title);
+            notification->setText(msg);
+            notification->setIconName(icon);
+            notification->setUrgency(KNotification::CriticalUrgency);
+            notification->sendEvent();
+            m_peripheralBatteryNotifications.insert(udi, notification);
         }

         return true;
@@ -745,9 +758,7 @@ void Core::onBatteryChargePercentChanged(int percent, const QString &udi)
         const int previousPercent = m_peripheralBatteriesPercent.value(udi);
         m_peripheralBatteriesPercent[udi] = percent;

-        if (percent < previousPercent) {
-            emitBatteryChargePercentNotification(percent, previousPercent, udi);
-        }
+        emitBatteryChargePercentNotification(percent, previousPercent, udi);
         return;
     }

diff --git a/daemon/powerdevilcore.h b/daemon/powerdevilcore.h
index 95c8341eb..743f5cdc7 100644
--- a/daemon/powerdevilcore.h
+++ b/daemon/powerdevilcore.h
@@ -66,8 +66,6 @@ public:

     void emitRichNotification(const QString &evid, const QString &title, const QString &message = QString());

-    void emitNotification(const QString &eventId, const QString &title, const QString &message, const QString &iconName);
-
     enum class ChargeNotificationFlag {
         None,
         NotifyWhenAcPluggedIn,
@@ -174,6 +172,7 @@ private:
     QHash<QString, int> m_batteriesPercent;
     QHash<QString, int> m_peripheralBatteriesPercent;
     QHash<QString, bool> m_batteriesCharged;
+    QHash<QString, QPointer<KNotification>> m_peripheralBatteryNotifications;

     QPointer<KNotification> m_lowBatteryNotification;
     QTimer *const m_criticalBatteryTimer;
-- 
